{
  "items": [
    {
      "label": "FIGURE O.5",
      "kind": "chart",
      "title": "Limited gains in the Global Prosperity Gap due to a slowdown of global growth and an increase of global inequality during the COVID-19 pandemic",
      "bbox": [
        84,
        167,
        403,
        786
      ],
      "content": {
        "type": "stacked bar chart",
        "y_axis": "Annual growth (%)",
        "x_axis": "Time periods (1990–2000, 2000–2010, 2010–2019, 2019–2024 projected)",
        "legend": [
          "Contribution of mean growth",
          "Contribution of within-country inequality",
          "Contribution of between-country inequality",
          "Global Prosperity Gap growth rate"
        ],
        "data_points": {
          "1990–2000": {
            "mean_growth": -1.5,
            "within_country": 0.5,
            "between_country": 0.5,
            "global_prosperity_gap_growth_rate": -1.5
          },
          "2000–2010": {
            "mean_growth": -2.5,
            "within_country": 0.2,
            "between_country": 0.8,
            "global_prosperity_gap_growth_rate": -3.5
          },
          "2010–2019": {
            "mean_growth": -1.8,
            "within_country": 0.2,
            "between_country": 0.2,
            "global_prosperity_gap_growth_rate": -2.8
          },
          "2019–2024": {
            "mean_growth": -0.8,
            "within_country": 0.2,
            "between_country": 0.5,
            "global_prosperity_gap_growth_rate": -1.2
          }
        },
        "source": "World Bank calculations using data from the Poverty and Inequality Platform (version September 2024), https://pip.worldbank.org/.",
        "note": "A decrease in the Prosperity Gap is an improvement in welfare. Growth is calculated as the log difference. Change in the Prosperity Gap is the sum of the (negative) growth in the mean income and the decline in total inequality. Positive growth in the mean decreases (improves) the Prosperity Gap; thus, in the figure, the contribution of the mean growth is shown as the negative of mean growth. That is, for all the periods in the graph, there was positive growth in the global mean, which is displayed as a negative contribution. Inequality is measured using the inequality measure related to the Prosperity Gap. Change in total inequality is the sum of changes in between-country and within-country inequality. See annex 2B for further details."
      }
    }
  ]
}
